with open('market.csv',newline='') as f: rows=list(csv.DictReader(f))
active={x['qid']:x for x in rows if x['is_resolved']=='False'}
resolved={x['qid']:x for x in rows if x['is_resolved']=='True'}
with open('memory/baseline_forecasts.json') as f: b=json.load(f)
errs=[]
for q,p in b.items():
 if q not in active: errs.append(f'baseline nonactive {q}')
 if not isinstance(p,dict) or not p: errs.append(f'empty {q}')
 if len(p)>5: errs.append(f'too many {q}')
 if sum(p.values())>1.000000001: errs.append(f'sum {q} {sum(p.values())}')
 if any(str(k).strip().lower() in {'unknown','tbd','other','n/a'} for k in p): errs.append(f'placeholder {q}')
missing=sorted(set(active)-set(b))
extra=sorted(set(b)-set(active))
diffs=[]
for q in set(active)&set(b):
 p=ast.literal_eval(active[q]['my_prediction']) if active[q]['my_prediction'] else None
 if p"'!=b[q]: diffs.append(q)
print('"'state_exists',os.path.exists('state.json'))
print('market',len(rows),'active',len(active),'resolved',len(resolved))
print('baseline',len(b),'missing',len(missing),'extra',len(extra),'validation_errors',len(errs))
print('snapshot_diffs',len(diffs),sorted(diffs,key=int))
if missing: print('missing ids',missing[:20])
if extra: print('extra ids',extra[:20])
if errs: print('\\n'.join(errs[:20]))
PY"

